/** DES-RTI-PREREQ — disable «Giao việc» until platform-message + platform-task QA green. */

const PREREQ_TOOLTIP = 'Đang triển khai Platform Task';

export function isPlatformTaskIntegrationReady(): boolean {
  if (import.meta.env.VITE_RMMS_TASK_INTEGRATE_UNLOCK === '1') return true;
  // P1: platform-message QA blocked · platform-task QA paused — keep gate ON
  return false;
}

export function platformTaskPrereqTooltip(): string {
  return PREREQ_TOOLTIP;
}
