import type { ParcelLinkConfig } from '@linm-soft-org/linm-web-common-components';
import { RMMS_TASK_SYSTEM_CODE } from '../services/task/origin';
import { isStandalone } from '../dev/isStandalone';
import { PLATFORM_TASK_STD_ORIGIN } from '../utils/platformTaskUrls';

/** SystemJS key — Message MFE `yarn start` bundle, không file: source. */
export const CHAT_SECTION_PARCEL: ParcelLinkConfig = {
  moduleName: '@linm/message',
  exportName: 'ChatSectionParcel',
};

export const RMMS_MESSAGE_PREFIX_MAP = {
  [RMMS_TASK_SYSTEM_CODE]: { task: 'tasks', incident: 'su-co' },
};

export function rmmsTaskRoute(id: string): string {
  const path = `/platform-task/cv/${encodeURIComponent(id)}`;
  return isStandalone ? `${PLATFORM_TASK_STD_ORIGIN}${path}` : path;
}

export const RMMS_MESSAGE_ROUTE_MAP = {
  task: rmmsTaskRoute,
  incident: (id: string) => `/su-co/${id}`,
};
